SELECT EXISTS(
    SELECT 1 FROM sys_role_permission
    WHERE role_id = #{roleId} AND permission_id = #{permissionId}
)

SELECT EXISTS(
    SELECT 1
    FROM sys_user_role user_role
    JOIN sys_role role ON role.id = user_role.role_id
    JOIN sys_role_permission role_permission ON role_permission.role_id = role.id
    WHERE user_role.user_id = #{userId}
      AND role.status = 'ENABLED'
      AND role_permission.permission_id = #{permissionId}
      AND role_permission.effect = #{effect}
)

mapper.update:
UPDATE sys_role_permission
SET effect = #{effect}, assigned_at = CURRENT_TIMESTAMP
WHERE role_id = #{roleId} AND permission_id = #{permissionId}
